// src/modes/learning/sorting/Sorting.view.js
import { createElement, clear, on } from '@utils/dom';
import { getImageUrl } from '@services/imageService';
import { logger } from '@utils/logger';

/**
 * Рендерит игру "Сортировка"
 */
export function renderSortingGame(container, state, onDrop) {
  logger.debug(`🔄 Rendering Sorting Game, ${state.remainingCards.length} cards left`);
  clear(container);

  const wrap = createElement('div', { className: 'grid-container flex-mode' });
  const area = createElement('div', { className: 'sorting-area' });

  // Карточки для сортировки (горизонтальный ряд)
  const cardsWrap = createElement('div', { className: 'sorting-cards' });
  cardsWrap.style.display = 'flex';
  cardsWrap.style.flexWrap = 'nowrap';
  cardsWrap.style.overflowX = 'auto';
  cardsWrap.style.gap = 'var(--spacing-sm)';
  cardsWrap.style.padding = 'var(--spacing-sm)';
  cardsWrap.style.minHeight = '100px';

  state.remainingCards.forEach(card => {
    const cardEl = createElement('div', {
      className: 'sort-card',
      draggable: true,
      'data-id': card.id,
    });

    if (card.imageId) {
      const img = createElement('img', { className: 'icon-sm' });
      getImageUrl(card.imageId).then(url => {
        if (url) img.src = url;
        else img.textContent = card.emoji || '📄';
      });
      cardEl.appendChild(img);
    } else {
      cardEl.textContent = card.emoji || '📄';
    }

    const label = createElement('span', {}, card.text);
    cardEl.appendChild(label);

    cardEl.addEventListener('dragstart', (e) => {
      e.dataTransfer.setData('text/plain', JSON.stringify({
        type: 'sorting-card',
        id: card.id,
      }));
      e.dataTransfer.effectAllowed = 'move';
    });

    cardsWrap.appendChild(cardEl);
  });

  area.appendChild(cardsWrap);

  // Зоны сортировки
  const zonesWrap = createElement('div', { className: 'sorting-zones' });
  state.zones.forEach(zone => {
    const zoneEl = createElement('div', {
      className: 'sorting-zone',
      'data-category-id': zone.categoryId,
    });

    const title = createElement('div', { className: 'zone-title' }, zone.name);
    zoneEl.appendChild(title);

    const itemsWrap = createElement('div', { className: 'zone-items' });
    zone.items.forEach(item => {
      const itemEl = createElement('span', {
        className: `placed-item ${item.isCorrect ? 'correct' : 'wrong'}`,
      }, `${item.emoji || ''} ${item.text}`);
      itemsWrap.appendChild(itemEl);
    });
    zoneEl.appendChild(itemsWrap);

    zoneEl.addEventListener('dragover', (e) => {
      e.preventDefault();
      e.dataTransfer.dropEffect = 'move';
    });
    zoneEl.addEventListener('drop', (e) => {
      e.preventDefault();
      const rawData = e.dataTransfer.getData('text/plain');
      if (!rawData) return;
      try {
        const data = JSON.parse(rawData);
        if (data.type === 'sorting-card') {
          onDrop(data.id, zone.categoryId);
        }
      } catch {
        // Если не JSON, пробуем как простой id
        onDrop(rawData, zone.categoryId);
      }
    });

    zonesWrap.appendChild(zoneEl);
  });
  area.appendChild(zonesWrap);

  wrap.appendChild(area);
  container.appendChild(wrap);

  // Если карточек не осталось – сообщаем
  if (state.remainingCards.length === 0) {
    const doneMsg = createElement('div', {
      style: 'text-align:center; padding:20px; font-size:18px; color: var(--primary);',
    }, 'Все карточки отсортированы! ✅');
    wrap.appendChild(doneMsg);
  }
}

