/* Нижняя панель – теперь в потоке, не абсолютная */
.bottom-panel {
  flex-shrink: 0;
  background: var(--bg);
  padding: var(--spacing-sm) var(--spacing-md);
  padding-bottom: calc(var(--spacing-sm) + env(safe-area-inset-bottom, 0px));
  display: flex;
  flex-direction: column;
  gap: var(--spacing-sm);
  border-top: 1px solid var(--border);
  transition: transform 0.2s ease;
}

/* При открытии клавиатуры панель поднимается вместе с ней */
.keyboard-open .bottom-panel {
  transform: translateY(calc(-1 * var(--keyboard-offset, 0px)));
}

/* Если панель скрыта – убираем её */
.bottom-panel.hidden {
  display: none !important;
}

.quick-buttons {
  display: flex;
  gap: var(--spacing-sm);
  overflow-x: auto;
  scrollbar-width: none;
  padding-bottom: 2px;
}
.quick-buttons::-webkit-scrollbar { display: none; }

.quick-btn {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 20px;
  padding: var(--spacing-xs) var(--spacing-md);
  white-space: nowrap;
  cursor: pointer;
  font-size: 14px;
  display: flex;
  align-items: center;
  gap: var(--spacing-sm);
  flex-shrink: 0;
  transition: background var(--transition);
}
.quick-btn:active { background: #e9ecef; }
.quick-btn img { width: 24px; height: 24px; object-fit: contain; }

buttons.css.content:
/* ============================================================
   УНИВЕРСАЛЬНЫЕ КНОПКИ (стиль как у mode-btn)
   ============================================================ */

.btn,
.btn-secondary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 8px 16px;
  border-radius: 20px;
  border: 1px solid var(--border);
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.2s, color 0.2s, border-color 0.2s, transform 0.1s;
  user-select: none;
  text-align: center;
  min-height: 36px;
  min-width: 60px;
  background: #e9ecef;
  color: var(--text-secondary);
  box-sizing: border-box;
  white-space: nowrap;
}

.btn:active,
.btn-secondary:active {
  transform: scale(0.96);
}

.btn-primary {
  background: var(--primary);
  border-color: var(--primary);
  color: #000;
}
.btn-primary:hover {
  background: var(--primary-dark);
  border-color: var(--primary-dark);
  color: #fff;
}
.btn-primary:active {
  background: var(--primary-dark);
}

.btn-secondary {
  background: #e9ecef;
  border-color: #ced4da;
  color: var(--text-secondary);
}
.btn-secondary:hover {
  background: #dee2e6;
}

.btn-danger {
  background: #fff;
  border-color: var(--danger);
  color: var(--danger);
  border-radius: 20px; /* как у всех кнопок */
}
.btn-danger:hover {
  background: var(--danger);
  border-color: var(--danger);
  color: #fff;
}
.btn-danger:active {
  background: #b71c1c;
}

.btn-sm {
  padding: 4px 12px;
  font-size: 12px;
  min-height: 28px;
  min-width: 28px;
}

card.css.content:
/* Сетка */
.tiles-grid {
  display: grid;
  gap: var(--spacing-sm);
  grid-template-columns: repeat(auto-fill, minmax(80px, 1fr));
}

/* Карточка */
.card {
  background: var(--surface);
  border: 2px solid var(--border);
  border-radius: var(--radius-sm);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  height: 130px;
  cursor: pointer;
  box-shadow: var(--shadow);
  transition: transform 0.15s, border-color 0.15s;
}
.card:active { transform: scale(0.96); }
.card--active {
  border-color: var(--primary);
  box-shadow: 0 0 0 2px var(--primary);
}
.card--add {
  background: var(--primary-light);
  border: 2px dashed var(--primary);
}
.card__bg {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 48px;
  background-size: contain;
  background-position: center;
}
.card__label {
  padding: var(--spacing-xs);
  text-align: center;
  font-weight: 600;
  font-size: 14px;
  border-top: 1px solid var(--border);
  background: rgba(255,255,255,0.9);
}

categories.css.content:
/* Категории */
.categories-wrap {
  overflow-x: auto;
  scrollbar-width: none;
  border-bottom: 1px solid var(--border);
  background: var(--surface);
  flex-shrink: 0;
}
.categories-wrap::-webkit-scrollbar {
  display: none;
}
.categories {
  display: flex;
  gap: var(--spacing-xs);
  padding: var(--spacing-sm) var(--spacing-md);
  flex-wrap: nowrap;
}
.category {
  background: #e9ecef;
  padding: var(--spacing-xs) var(--spacing-md);
  border-radius: 20px;
  white-space: nowrap;
  cursor: pointer;
  font-size: 14px;
  font-weight: 500;
  color: var(--text-secondary);
  transition: background var(--transition), color var(--transition);
  display: flex;
  align-items: center;
  gap: var(--spacing-xs);
  position: relative;
}
.category.active {
  background: var(--primary);
  color: #000;
}
.category:active {
  transform: scale(0.96);
}
.category-add {
  background: var(--primary-light);
  border: 1px dashed var(--primary);
  color: var(--text);
}
.category-hidden {
  text-decoration: line-through;
  opacity: 0.6;
}
/* Редактирование категорий */
.category .cat-actions {
  display: none;
  gap: var(--spacing-xs);
}
.category.edit-mode .cat-actions {
  display: flex;
}
.category .cat-actions button {
  background: transparent;
  border: none;
  cursor: pointer;
  font-size: 14px;
  padding: 0 var(--spacing-xs);
}
.category.drag-over {
  background: var(--primary-light);
  border: 2px dashed var(--primary);
  transform: scale(1.05);
  box-shadow: var(--shadow);
}

custom-select.css.content:
/* src/styles/components/custom-select.css */

.custom-select {
  position: relative;
  width: 100%;
  min-height: 36px;
}

.custom-select-button {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 8px 12px;
  padding-left: 16px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border);
  border-left: 3px solid var(--primary);
  background: var(--surface);
  color: var(--text);
  font-size: 14px;
  font-family: var(--font);
  cursor: pointer;
  transition: border-color 0.2s, box-shadow 0.2s;
  min-height: 36px;
  appearance: none;
  -webkit-appearance: none;
  background-image: url("data:image/svg+xml;charset=UTF-8,%3csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%23495057' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'%3e%3cpolyline points='6 9 12 15 18 9'%3e%3c/polyline%3e%3c/svg%3e");
  background-repeat: no-repeat;
  background-position: right 8px center;
  background-size: 16px;
  padding-right: 32px;
}

.custom-select-button:focus {
  border-color: var(--primary);
  outline: none;
  box-shadow: 0 0 0 3px rgba(76, 175, 80, 0.2);
}

.custom-select-dropdown {
  position: absolute;
  top: calc(100% + 4px);
  left: 0;
  right: 0;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  box-shadow: var(--shadow);
  max-height: 200px;
  overflow-y: auto;
  display: none;
  z-index: 1000;
}

.custom-select.open .custom-select-dropdown {
  display: block;
}

.custom-select-item {
  padding: 8px 12px;
  padding-left: 16px;
  cursor: pointer;
  border-radius: 6px;
  transition: background 0.15s;
  color: var(--text);
  border-left: 3px solid transparent;
}

.custom-select-item:hover {
  background: var(--primary-light);
}

.custom-select-item.selected {
  border-left: 3px solid var(--primary);
  background: var(--surface);
  font-weight: 500;
}

editing.css.content:
/* Режим редактирования – зелёный фон для всей страницы */
body.editing-mode {
  background-color: var(--primary-light);
}

body.editing-mode #app {
  background-color: var(--primary-light);
}

body.editing-mode .app-header {
  background-color: var(--primary-light);
  border-bottom-color: var(--primary);
}

body.editing-mode .mode-bar {
  background-color: var(--primary-light);
  border-bottom-color: var(--primary);
}

body.editing-mode .main-area {
  background-color: var(--primary-light);
}

/* Можно также добавить для других элементов, но пока достаточно */

editor.css.content:
/* Редактор карточек и категорий */
.editor-modal {
  padding: 0;
  width: 100%;
}
.editor-modal .tile-bg {
  width: 100%;
  height: 150px;
  border-radius: var(--radius-sm);
  margin-bottom: var(--spacing-md);
  background-color: #f1f3f5;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 64px;
  cursor: pointer;
  border: 2px dashed var(--border);
  transition: border-color var(--transition);
  background-size: contain;
  background-position: center;
  background-repeat: no-repeat;
}
.editor-modal .tile-bg:hover {
  border-color: var(--primary);
}
.editor-modal input,
.editor-modal select {
  width: 100%;
  margin: var(--spacing-xs) 0;
  padding: var(--spacing-sm) var(--spacing-md);
  border-radius: var(--radius-sm);
  border: 1px solid var(--border);
  font-size: 16px;
  box-sizing: border-box;
}
.editor-modal .btn-row {
  display: flex;
  gap: var(--spacing-sm);
  margin-top: var(--spacing-lg);
  justify-content: flex-end;
  width: 100%;
  flex-wrap: wrap;
}
.editor-modal .form-row {
  display: flex;
  gap: var(--spacing-sm);
  align-items: center;
  width: 100%;
  margin: var(--spacing-xs) 0;
}
.editor-modal .form-row label {
  min-width: 60px;
  font-size: 14px;
  color: var(--text-secondary);
}
.editor-modal .form-row input {
  flex: 1;
}
.forms-block {
  width: 100%;
  margin-top: var(--spacing-sm);
  border-top: 1px solid var(--border);
  padding-top: var(--spacing-sm);
}

forms.css.content:
/* ============================================================
   ПОЛЯ ВВОДА, SELECT, TEXTAREA
   ============================================================ */

input[type="text"],
input[type="number"],
input[type="time"],
input[type="password"],
textarea,
select {
  padding: 8px 12px;
  padding-left: 16px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border);
  border-left: 3px solid var(--primary);
  font-size: 14px;
  font-family: var(--font);
  background: var(--surface);
  color: var(--text);
  transition: border-color 0.2s, box-shadow 0.2s;
  min-height: 36px;
  width: 100%;
  box-sizing: border-box;
}

select {
  appearance: auto;
  -webkit-appearance: auto;
  background-image: none;
}

select:focus,
input:focus,
textarea:focus {
  border-color: var(--primary);
  outline: none;
  box-shadow: 0 0 0 3px rgba(76, 175, 80, 0.2);
}

textarea {
  resize: vertical;
  min-height: 80px;
}

/* ============================================================
   СТИЛИЗАЦИЯ ПОЛЗУНКОВ (RANGE)
   ============================================================ */

/* Общий контейнер для строки с ползунком */
.form-row:has(input[type="range"]) {
  display: flex;
  align-items: center;
  gap: var(--spacing-sm);
}

.form-row:has(input[type="range"]) label {
  min-width: 80px;
  flex-shrink: 0;
}

.form-row:has(input[type="range"]) input[type="range"] {
  flex: 1;
  min-width: 0;
}

.form-row:has(input[type="range"]) span {
  min-width: 32px;
  text-align: right;
  font-weight: 500;
  color: var(--text-secondary);
  flex-shrink: 0;
}

input[type="range"] {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 6px;
  background: var(--border);
  border-radius: 3px;
  outline: none;
  transition: background 0.2s;
  padding: 0;
  border: none;
  min-height: auto;
}

/* Трек в Chrome/Safari/Edge */
input[type="range"]::-webkit-slider-runnable-track {
  height: 6px;
  background: var(--border);
  border-radius: 3px;
}

/* Трек в Firefox */
input[type="range"]::-moz-range-track {
  height: 6px;
  background: var(--border);
  border-radius: 3px;
  border: none;
}

/* Ползунок (thumb) в Chrome/Safari/Edge */
input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 20px;
  height: 20px;
  background: var(--primary);
  border-radius: 50%;
  cursor: pointer;
  margin-top: -7px;
  border: 2px solid var(--surface);
  box-shadow: var(--shadow);
  transition: background 0.2s, transform 0.1s;
}

/* Ползунок (thumb) в Firefox */
input[type="range"]::-moz-range-thumb {
  width: 20px;
  height: 20px;
  background: var(--primary);
  border-radius: 50%;
  cursor: pointer;
  border: 2px solid var(--surface);
  box-shadow: var(--shadow);
}

/* Ховер для ползунка */
input[type="range"]::-webkit-slider-thumb:hover {
  background: var(--primary-dark);
  transform: scale(1.05);
}

input[type="range"]::-moz-range-thumb:hover {
  background: var(--primary-dark);
  transform: scale(1.05);
}

/* Фокус – подсветка трека */
input[type="range"]:focus::-webkit-slider-runnable-track {
  background: var(--primary-light);
}

input[type="range"]:focus::-moz-range-track {
  background: var(--primary-light);
}

/* Стили для модалок */
.modal-body select,
.modal-body input[type="text"],
.modal-body input[type="number"],
.modal-body input[type="time"] {
  background-color: var(--surface);
}

/* Стили для опций (ограниченная поддержка) */
select option {
  border-radius: 6px;
  padding: 6px 12px;
  background: var(--surface);
  color: var(--text);
}

select option:checked {
  background: var(--surface);
  border-left: 3px solid var(--primary);
  padding-left: 16px;
}

grid.css.content:
/* Основной контейнер для контента внутри main-area */
.grid-container {
  flex: 1;
  overflow-y: auto;
  padding: var(--grid-padding, var(--spacing-sm));
  background: var(--surface);
  border: 2px solid var(--border);
  border-radius: var(--radius);
  margin: var(--spacing-sm) var(--spacing-md) var(--spacing-sm) var(--spacing-md);
  min-height: 0; /* предотвращает переполнение */
}

/* Когда есть нижняя панель – добавляем отступ снизу */
.main-area.has-panel .grid-container {
  margin-bottom: calc(130px + var(--keyboard-offset, 0px));
}

/* Режимы без панели – отступа нет */
.main-area.no-panel .grid-container {
  margin-bottom: var(--spacing-sm);
}

/* Специальный режим "Написать" – текстовая область */
.grid-container.write-mode {
  display: flex;
  flex-direction: column;
  padding: 0;
  border: none;
  background: transparent;
  margin: var(--spacing-sm) var(--spacing-md) calc(130px + var(--keyboard-offset, 0px)) var(--spacing-md);
}
.grid-container.write-mode textarea {
  flex: 1;
  width: 100%;
  padding: var(--spacing-lg);
  border: 2px solid var(--primary);
  border-radius: var(--radius);
  background: var(--surface);
  font-size: 20px;
  resize: none;
  outline: none;
  font-family: var(--font);
  box-sizing: border-box;
  min-height: 0;
}

header.css.content:
.app-header {
  flex-shrink: 0;
  background: var(--surface);
  border-bottom: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: flex-end;
  padding: 4px 12px;
  gap: var(--spacing-sm);
  z-index: 10;
}
.back-btn { display: none; } /* пока скрыта */
.profile-fab {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 50%;
  width: 34px;
  height: 34px;
  font-size: 20px;
  cursor: pointer;
  box-shadow: var(--shadow);
  flex-shrink: 0;
  margin-left: auto;
}
.mode-bar {
  display: flex;
  gap: var(--spacing-xs);
  padding: var(--spacing-sm);
  overflow-x: auto;
  scrollbar-width: none;
  flex: 1;
  background: var(--surface);
}
.mode-bar::-webkit-scrollbar { display: none; }
.mode-btn {
  padding: var(--spacing-sm) var(--spacing-md);
  border-radius: 20px;
  background: #e9ecef;
  border: none;
  font-weight: 600;
  font-size: 14px;
  white-space: nowrap;
  cursor: pointer;
  transition: background var(--transition), color var(--transition);
  color: var(--text-secondary);
}
.mode-btn.active {
  background: var(--primary);
  color: #000;
}
.mode-btn:active { transform: scale(0.96); }

layout.css.content:
/* src/styles/components/layout.css */
.main-area {
  display: flex;
  flex-direction: column;
  flex: 1;
  overflow: hidden;
  background: var(--bg);
  position: relative;
}

.main-content {
  flex: 1;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  min-height: 0; /* важно для корректного сжатия */
}

/* Стили для контейнера сетки внутри .main-content */
.main-content .grid-container {
  flex: 1;
  overflow-y: auto;
  padding: var(--grid-padding, var(--spacing-sm));
  background: var(--surface);
  border: 2px solid var(--border);
  border-radius: var(--radius);
  margin: var(--spacing-sm) var(--spacing-md) var(--spacing-sm) var(--spacing-md);
  min-height: 0;
}

/* Когда есть нижняя панель – добавляем отступ снизу для grid-container */
.main-area.has-panel .grid-container {
  margin-bottom: calc(130px + var(--keyboard-offset, 0px));
}

/* Нижняя панель – фиксируется внизу */
.bottom-panel {
  flex-shrink: 0;
  background: var(--bg);
  padding: var(--spacing-sm) var(--spacing-md);
  padding-bottom: calc(var(--spacing-sm) + env(safe-area-inset-bottom, 0px));
  display: flex;
  flex-direction: column;
  gap: var(--spacing-sm);
  border-top: 1px solid var(--border);
  transition: transform 0.2s ease;
}

/* При открытии клавиатуры панель поднимается вместе с ней */
.keyboard-open .bottom-panel {
  transform: translateY(calc(-1 * var(--keyboard-offset, 0px)));
}

/* Если панель скрыта – убираем её */
.bottom-panel.hidden {
  display: none !important;
}

modal.css.content:
/* ============================================================
   МОДАЛКИ
   ============================================================ */

.modal {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: rgba(0, 0, 0, 0.6);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1000;
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.25s ease, visibility 0.25s ease;
  backdrop-filter: blur(2px);
  padding: var(--spacing-lg);
}

.modal.visible {
  opacity: 1;
  visibility: visible;
}

.modal-content {
  background: var(--surface);
  width: 100%;
  max-width: 600px;
  max-height: 95vh; /* увеличен с 90vh */
  border-radius: var(--radius);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.3);
}

.modal-header {
  padding: var(--spacing-lg) var(--spacing-xl) var(--spacing-md);
  border-bottom: 1px solid var(--border);
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-shrink: 0;
}

.modal-title-wrap {
  display: flex;
  align-items: center;
  gap: var(--spacing-md);
}

.modal-icon {
  font-size: 48px;
  line-height: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 64px;
  height: 64px;
  background: var(--primary-light);
  border-radius: var(--radius-sm);
  border: 2px solid var(--primary);
  box-shadow: var(--shadow);
}

.modal-header h3 {
  margin: 0;
  font-size: 20px;
}

.modal-body {
  flex: 1;
  overflow-y: auto;
  padding: var(--spacing-md) var(--spacing-xl); /* уменьшен вертикальный паддинг */
  display: flex;
  flex-direction: column;
  align-items: center;
}

.modal-body > * {
  width: 100%;
  max-width: 100%;
}

.modal-footer {
  padding: var(--spacing-md) var(--spacing-xl);
  border-top: 1px solid var(--border);
  display: flex;
  justify-content: flex-end;
  gap: var(--spacing-sm);
  flex-shrink: 0;
}

.btn-close {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  border: none;
  background: transparent;
  font-size: 24px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  transition: background 0.2s;
  color: var(--text-secondary);
}

.btn-close:hover {
  background: rgba(0, 0, 0, 0.05);
}

/* Превью иконки в редакторе профиля */
.profile-preview {
  display: flex;
  justify-content: center;
  margin-bottom: var(--spacing-md);
}

.profile-preview-icon {
  width: 80px;
  height: 80px;
  border-radius: var(--radius);
  background: var(--primary-light);
  border: 3px solid var(--primary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 48px;
  box-shadow: var(--shadow);
}

mode-bar.css.content:
.mode-bar {
  display: flex;
  gap: var(--spacing-xs);
  padding: var(--spacing-sm) var(--spacing-sm);
  overflow-x: auto;
  scrollbar-width: none;
  flex-wrap: nowrap;
  background: var(--surface);
  border-bottom: 1px solid var(--border);
  flex: 1;
}
.mode-bar::-webkit-scrollbar {
  display: none;
}
.mode-btn {
  padding: var(--spacing-sm) var(--spacing-md);
  border-radius: 20px;
  background: #e9ecef;
  border: none;
  font-weight: 600;
