// src/utils/dom.js
export function createElement(tag, attrs = {}, children = null) {
  const el = document.createElement(tag);
  for (const [key, value] of Object.entries(attrs)) {
    if (key === 'className') el.className = value;
    else if (key === 'style' && typeof value === 'object') Object.assign(el.style, value);
    else el.setAttribute(key, value);
  }
  if (children !== null && children !== undefined) {
    if (typeof children === 'string' || typeof children === 'number') {
      el.textContent = String(children);
    } else if (Array.isArray(children)) {
      children.forEach(c => {
        if (c instanceof Node) el.appendChild(c);
        else if (c !== null) el.appendChild(document.createTextNode(String(c)));
      });
    } else if (children instanceof Node) {
      el.appendChild(children);
    } else {
      el.textContent = String(children);
    }
  }
  return el;
}

export function clear(el) {
  while (el.firstChild) el.removeChild(el.firstChild);
}

// ✅ Добавляем вспомогательные функции
export function on(el, event, handler, options = {}) {
  el.addEventListener(event, handler, options);
  return () => el.removeEventListener(event, handler, options);
}

export function off(el, event, handler, options = {}) {
  el.removeEventListener(event, handler, options);
}

export function delegate(el, event, selector, handler) {
  const wrapped = (e) => {
    const target = e.target.closest(selector);
    if (target && el.contains(target)) handler(e, target);
  };
  return on(el, event, wrapped);
}

dragdrop.js.content:
import { getElementIds, reorderArray } from './array';

export function makeSortable(container, options) {
  const { itemSelector = '[data-id]', onReorder = null } = options;
  let draggedId = null;

  const onDragStart = (e) => {
    const item = e.target.closest(itemSelector);
    if (!item) return;
    draggedId = item.dataset.id;
    e.dataTransfer.setData('text/plain', draggedId);
    e.dataTransfer.effectAllowed = 'move';
    item.classList.add('dragging');
  };

  const onDragEnd = (e) => {
    const item = e.target.closest(itemSelector);
    if (item) item.classList.remove('dragging');
    draggedId = null;
  };

  const onDragOver = (e) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
  };

  const onDrop = (e) => {
    e.preventDefault();
    const targetItem = e.target.closest(itemSelector);
    if (!targetItem) return;
    const targetId = targetItem.dataset.id;
    if (!draggedId || draggedId === targetId) return;

    const ids = getElementIds(container, itemSelector);
    const fromIndex = ids.indexOf(draggedId);
    const toIndex = ids.indexOf(targetId);
    if (fromIndex === -1 || toIndex === -1) return;

    const newOrder = reorderArray(ids, fromIndex, toIndex);
    if (onReorder) onReorder(newOrder);
    draggedId = null;
  };

  container.addEventListener('dragstart', onDragStart);
  container.addEventListener('dragend', onDragEnd);
  container.addEventListener('dragover', onDragOver);
  container.addEventListener('drop', onDrop);

  return () => {
    container.removeEventListener('dragstart', onDragStart);
    container.removeEventListener('dragend', onDragEnd);
    container.removeEventListener('dragover', onDragOver);
    container.removeEventListener('drop', onDrop);
  };
}

